using System.Reflection;
using System.Runtime.CompilerServices;
using System.Text.Json;
using CombatSolver;
using HarmonyLib;

namespace OfflineSearchHarness;

// Counts exact recorded action lineage only. No cache, simulation bypass or safety claim.
internal static class ExactReplayLineageProbe
{
    private const int Limit = 250_000;
    private static readonly object Gate = new();
    private static readonly ConditionalWeakTable<CombatRootSnapshot, Id> Roots = new();
    private static readonly ConditionalWeakTable<CombatBeamSolver, Member> Members = new();
    private static readonly ConditionalWeakTable<SimulationSnapshot, Tag> Tags = new();
    private static readonly Dictionary<string, int> Actions = new(StringComparer.Ordinal);
    private static readonly Dictionary<Prefix, Seen> Prefixes = [];
    private static readonly Dictionary<int, DepthCounts> Depths = [];
    private static readonly List<object> Differences = [];
    private static readonly ConditionalWeakTable<SearchNode, Tag> Nodes = new();
    private static readonly Dictionary<(int Root, int Parent, string Token), int> NodePrefixes = [];
    private static readonly Dictionary<int, Seen> NodeResults = [];
    private static readonly Dictionary<int, DepthCounts> NodeDepths = [];
    private static readonly List<object> NodeDifferences = [];
    private static long _nodeActions, _nodePending, _nodeUnexplainedRoot, _nodeBypass;
    private static int _nextRoot, _nextMember, _nextPrefix;
    private static long _total, _plain, _resumption, _unknownParent, _pending, _bypass;
    private static readonly FieldInfo RootField = typeof(CombatBeamSolver)
        .GetFields(BindingFlags.Instance | BindingFlags.NonPublic)
        .Single(f => f.FieldType == typeof(CombatRootSnapshot));
    private sealed record Id(int Value);
    private sealed record Member(int Value, int Root);
    private sealed record Tag(int Id, int Depth);
    private readonly record struct Prefix(int Root, int Parent, int Action, int Turn, int Prior, bool Capture, bool Setup);
    private sealed record Seen(int Id, int Member, Values Result);
    private readonly record struct Values(StateFingerprint Key, int Hp, int MaxHp, int Lost,
        int Recovered, int Potions, int PotionCost, int DeathSave, int History, int Shuffles,
        SearchBoundaryReason Boundary, bool Dead, bool Won, long ScoreBits)
    {
        internal static Values From(SimulationSnapshot s) => new(s.StateKey, s.PlayerHp,
            s.PlayerMaxHp, s.CumulativePlayerHpLost, s.RecoveredPlayerHp, s.PotionUseCount,
            s.PotionStrategicCost, s.DeathSaveUseCount, s.HistoryEntryCount, s.ShufflesCrossed,
            s.BoundaryReason, s.PlayerDead, s.AllEnemiesDead, BitConverter.DoubleToInt64Bits(s.Score));
    }
    private sealed class DepthCounts
    {
        public long Tracked, SameMember, CrossMember, ResultKeyMismatch, SelectedStateMismatch, ScoreMismatch;
    }

    internal static void Install(string output)
    {
        if (Environment.GetEnvironmentVariable("OFFLINE_HARNESS_EXACT_LINEAGE_PROBE") != "1") return;
        GameBootstrap.Harmony.Patch(AccessTools.Method(typeof(CombatBeamSolver), "CreateExpansionWorker"),
            postfix: new HarmonyMethod(typeof(ExactReplayLineageProbe), nameof(Worker)));
        GameBootstrap.Harmony.Patch(AccessTools.Method(typeof(CombatBeamSolver), "ReplayTurnSetup"),
            postfix: new HarmonyMethod(typeof(ExactReplayLineageProbe), nameof(Setup)));
        GameBootstrap.Harmony.Patch(AccessTools.Method(typeof(CombatBeamSolver), "Replay"),
            postfix: new HarmonyMethod(typeof(ExactReplayLineageProbe), nameof(Replay)));
        GameBootstrap.Harmony.Patch(AccessTools.Method(typeof(CombatBeamSolver), "ReplayAction"),
            postfix: new HarmonyMethod(typeof(ExactReplayLineageProbe), nameof(Action)));
        AppDomain.CurrentDomain.ProcessExit += (_, _) =>
        {
            lock (Gate)
                File.WriteAllText(Path.Combine(output, "exact-replay-lineage.json"), JsonSerializer.Serialize(new
                {
                    observationOnly = true, limit = Limit, roots = _nextRoot, members = _nextMember,
                    totalReplay = _total, plainReplay = _plain, resumptionExcluded = _resumption,
                    unknownParent = _unknownParent, pendingExcluded = _pending, limitBypass = _bypass,
                    retainedPrefixes = Prefixes.Count, retainedActionTokens = Actions.Count,
                    depths = Depths, differences = Differences,
                    nodeLineage = new { total = _nodeActions, pendingExcluded = _nodePending,
                        unexplainedRoot = _nodeUnexplainedRoot, limitBypass = _nodeBypass,
                        retainedPrefixes = NodePrefixes.Count, retainedResults = NodeResults.Count,
                        depths = NodeDepths, differences = NodeDifferences,
                        scope = "Uniform ReplayAction return, including resumes. Ordered node parent chain is read without Actions materialization. Roots with omitted earlier actions are refused. Root token also includes the initial node state key and setup choices; this is still an opportunity counter, not a complete transfer proof." },
                    scope = "Exact frozen root identity plus recorded ordered setup/action lineage and replay input flags. Weak snapshot/member tags; retained keys contain pure IDs/strings and selected values only. No simulation/model/history graphs. Resumption and missing lineage are explicitly excluded. Selected result equality is not full history, callback, RNG, policy or cache-safety proof. Instrumented time and RSS are not acceptance.",
                }, new JsonSerializerOptions { WriteIndented = true, IncludeFields = true }));
        };
    }

    private static Member MemberFor(CombatBeamSolver solver) => Members.GetValue(solver, value =>
    {
        CombatRootSnapshot root = (CombatRootSnapshot)RootField.GetValue(value)!;
        return new(++_nextMember, Roots.GetValue(root, _ => new(++_nextRoot)).Value);
    });

    private static void Worker(CombatBeamSolver __instance, CombatBeamSolver __result)
    {
        lock (Gate) Members.Add(__result, MemberFor(__instance));
    }

    private static int NodePrefix(int root, int parent, string token)
    {
        var key = (root, parent, token);
        if (NodePrefixes.TryGetValue(key, out int id)) return id;
        if (NodePrefixes.Count == Limit) { _nodeBypass++; return 0; }
        NodePrefixes.Add(key, id = NodePrefixes.Count + 1);
        return id;
    }

    private static Tag? NodeTag(int root, SearchNode node)
    {
        if (Nodes.TryGetValue(node, out Tag? tag)) return tag;
        if (node.Action is null)
        {
            if (node.Parent != null || node.ActionCount != 0) { _nodeUnexplainedRoot++; return null; }
            int id = NodePrefix(root, 0, "ROOT/" + node.Turn + "/" + node.Snapshot.StateKey
                + "/" + JsonSerializer.Serialize(node.GetTurnSetupChoices()));
            if (id == 0) return null;
            tag = new(id, 0);
        }
        else
        {
            if (node.Parent is null) { _nodeUnexplainedRoot++; return null; }
            Tag? parent = NodeTag(root, node.Parent);
            if (parent is null) return null;
            int id = NodePrefix(root, parent.Id, JsonSerializer.Serialize(node.Action));
            if (id == 0) return null;
            tag = new(id, parent.Depth + 1);
        }
        Nodes.Add(node, tag);
        return tag;
    }

    private static void Action(CombatBeamSolver __instance, SearchNode parent,
        PlanAction action, SimulationSnapshot __result)
    {
        lock (Gate)
        {
            _nodeActions++;
            if (__result.BoundaryReason == SearchBoundaryReason.PendingChoice) { _nodePending++; return; }
            Member member = MemberFor(__instance);
            Tag? tag = NodeTag(member.Root, parent);
            if (tag is null) return;
            int id = NodePrefix(member.Root, tag.Id, JsonSerializer.Serialize(action));
            if (id == 0) return;
            int depth = tag.Depth + 1;
            if (!NodeDepths.TryGetValue(depth, out DepthCounts? counts)) NodeDepths.Add(depth, counts = new());
            counts.Tracked++;
            Values values = Values.From(__result);
            if (NodeResults.TryGetValue(id, out Seen? first))
            {
                if (first.Member == member.Value) counts.SameMember++;
                else counts.CrossMember++;
                if (first.Result.Key != values.Key) counts.ResultKeyMismatch++;
                if ((first.Result with { ScoreBits = 0 }) != (values with { ScoreBits = 0 })) counts.SelectedStateMismatch++;
                if (first.Result.ScoreBits != values.ScoreBits) counts.ScoreMismatch++;
                if (first.Result != values && NodeDifferences.Count < 12)
                    NodeDifferences.Add(new { depth, firstMember = first.Member, currentMember = member.Value,
                        first = first.Result, current = values });
            }
            else NodeResults.Add(id, new(id, member.Value, values));
        }
    }

    private static void Setup(CombatBeamSolver __instance, IReadOnlyList<PlanCardChoice> choices,
        bool allowExecutionCapture, SimulationSnapshot __result)
    {
        string action = JsonSerializer.Serialize(choices);
        lock (Gate)
            Record(__instance, null, action, 0, 0, 0, allowExecutionCapture, true, __result);
    }

    private static void Replay(CombatBeamSolver __instance, IReadOnlyList<PlanAction> actions,
        SimulationSnapshot? parentSnapshot, int startingTurn, int priorActionCount,
        object? triggerRecorder, object? replayEvidence, object? roundCheckpoint,
        object? roundCheckpointCapture, object? cardChoiceCapture, object? cardChoiceFrame,
        object? potionChoiceFrame, bool allowExecutionCapture, object? continuationCapture,
        SimulationSnapshot __result)
    {
        lock (Gate)
        {
            _total++;
            if (triggerRecorder != null || replayEvidence != null || roundCheckpoint != null
                || roundCheckpointCapture != null || cardChoiceCapture != null || cardChoiceFrame != null
                || potionChoiceFrame != null || continuationCapture != null)
            { _resumption++; return; }
            _plain++;
            Record(__instance, parentSnapshot, JsonSerializer.Serialize(actions), actions.Count,
                startingTurn, priorActionCount, allowExecutionCapture, false, __result);
        }
    }

    private static void Record(CombatBeamSolver solver, SimulationSnapshot? parent, string action,
        int actionCount, int turn, int prior, bool capture, bool setup, SimulationSnapshot result)
    {
        if (result.BoundaryReason == SearchBoundaryReason.PendingChoice) { _pending++; return; }
        Tag? parentTag = null;
        if (parent != null && !Tags.TryGetValue(parent, out parentTag)) { _unknownParent++; return; }
        if (!Actions.TryGetValue(action, out int token))
        {
            if (Actions.Count == Limit) { _bypass++; return; }
            Actions.Add(action, token = Actions.Count + 1);
        }
        Member member = MemberFor(solver);
        Prefix key = new(member.Root, parentTag?.Id ?? 0, token, turn, prior, capture, setup);
        int depth = (parentTag?.Depth ?? 0) + actionCount;
        if (!Depths.TryGetValue(depth, out DepthCounts? counts)) Depths.Add(depth, counts = new());
        counts.Tracked++;
        Values values = Values.From(result);
        if (Prefixes.TryGetValue(key, out Seen? first))
        {
            if (first.Member == member.Value) counts.SameMember++;
            else counts.CrossMember++;
            if (first.Result.Key != values.Key) counts.ResultKeyMismatch++;
            if ((first.Result with { ScoreBits = 0 }) != (values with { ScoreBits = 0 }))
                counts.SelectedStateMismatch++;
            if (first.Result.ScoreBits != values.ScoreBits) counts.ScoreMismatch++;
            if (first.Result != values && Differences.Count < 12)
                Differences.Add(new { depth, firstMember = first.Member, currentMember = member.Value,
                    first = first.Result, current = values });
            Tags.Add(result, new(first.Id, depth));
        }
        else if (Prefixes.Count < Limit)
        {
            Seen seen = new(++_nextPrefix, member.Value, values);
            Prefixes.Add(key, seen);
            Tags.Add(result, new(seen.Id, depth));
        }
        else _bypass++;
    }
}

