                && HookNames.TryGetValue(method.Name, out MirroredHookMask mask)
                && method.GetBaseDefinition().DeclaringType == typeof(AbstractModel))
                result |= mask;
        }
        return result;
    }

    private sealed record Participation(MirroredHookMask Mask);
}

