using System.Reflection;
using System.Runtime.CompilerServices;
using HarmonyLib;
using MegaCrit.Sts2.Core.Hooks;
using MegaCrit.Sts2.Core.Models;

namespace CombatSolver.Engine.Common;

// Root-frozen dispatch metadata for mirrors and the native keyword no-op guard.
// Domain/native listener enumeration remains complete. External and patched hooks
// always retain the original dispatch path.
internal sealed class MirroredHookListenerFilter(bool enabled)
{
    // The projection removes the complete-list capacity pass and repeated getter reads.
    // These exact native getters are field reads in the audited game DLL. Unknown game
    // bodies or getter patches may observe those reads, so retain the complete producer.
    private static readonly Guid AuditedCardGetterModule = new("8a76776c-0ce1-4d4f-90bd-8cce653dad8e");
    private static readonly MethodInfo[] ProjectionReadMethods =
    [
        typeof(CardModel).GetProperty(nameof(CardModel.HasBeenRemovedFromState))!.GetMethod!,
        typeof(CardModel).GetProperty(nameof(CardModel.Affliction))!.GetMethod!,
        typeof(CardModel).GetProperty(nameof(CardModel.Enchantment))!.GetMethod!,
        typeof(PredictedCard).GetProperty(nameof(PredictedCard.Preview))!.GetMethod!,
    ];
    private readonly bool _projectionReadsArePure =
        typeof(CardModel).Module.ModuleVersionId == AuditedCardGetterModule
        && !ProjectionReadMethods.Any(method =>
            Harmony.GetPatchInfo(method) is { } patches && patches.Owners.Count != 0);

    // This filter belongs to one captured root. Only immutable runtime-type layouts
    // cross branches; receiver models remain exclusively in each returned snapshot.
    // A direct-mapped table has bounded retention and needs no worker-side lock.
    internal const int SharedLayoutSlots = 2048;
    private const int MaxSharedLayoutLength = 1024;
    private readonly MirroredHookListenerLayout?[] _sharedLayouts =
        enabled ? new MirroredHookListenerLayout?[SharedLayoutSlots] : [];
    // A root may be used by many lanes, but each counter cell has one writing thread.
    // The weak thread-local keys keep old root filters and their layouts collectible.
    [ThreadStatic] private static ConditionalWeakTable<MirroredHookListenerFilter, ThreadCounters>? _threadCounters;
    [ThreadStatic] private static WeakReference<MirroredHookListenerFilter>? _recentCounterOwner;
    [ThreadStatic] private static ThreadCounters? _recentCounters;
    private readonly object _counterGate = new();
    private ThreadCounters[] _counterCells = [];

    private sealed class ThreadCounters
    {
        internal long SharedHits, SharedMisses, SharedCollisions, SharedBypasses;
        internal long ListenerPrefixReuses, ListenerPrefixBuilds, ListenerSplitBuilds, ListenerWholeBuilds;
        internal long EffectivePrefixReuses, EffectivePrefixBuilds;
    }

    private ThreadCounters CurrentThreadCounters
    {
        get
        {
            if (_recentCounterOwner?.TryGetTarget(out MirroredHookListenerFilter? owner) == true
                && ReferenceEquals(owner, this))
                return _recentCounters!;
            ThreadCounters cell = (_threadCounters ??= new()).GetValue(this,
                static filter => filter.CreateThreadCounters());
            (_recentCounterOwner ??= new(null!)).SetTarget(this);
            _recentCounters = cell;
            return cell;
        }
    }

    private ThreadCounters CreateThreadCounters()
    {
        ThreadCounters cell = new();
        lock (_counterGate)
            Volatile.Write(ref _counterCells, [.. _counterCells, cell]);
        return cell;
    }

    internal int StatisticsShardCount => Volatile.Read(ref _counterCells).Length;

    internal HookListenerSegmentStatistics ListenerSegmentStatistics
    {
        get
        {
            long prefixReuses = 0, prefixBuilds = 0, splitBuilds = 0, wholeBuilds = 0;
            long effectiveReuses = 0, effectiveBuilds = 0;
            foreach (ThreadCounters cell in Volatile.Read(ref _counterCells))
            {
                prefixReuses += Volatile.Read(ref cell.ListenerPrefixReuses);
                prefixBuilds += Volatile.Read(ref cell.ListenerPrefixBuilds);
                splitBuilds += Volatile.Read(ref cell.ListenerSplitBuilds);
                wholeBuilds += Volatile.Read(ref cell.ListenerWholeBuilds);
                effectiveReuses += Volatile.Read(ref cell.EffectivePrefixReuses);
                effectiveBuilds += Volatile.Read(ref cell.EffectivePrefixBuilds);
            }
            return new(prefixReuses, prefixBuilds, splitBuilds, wholeBuilds, effectiveReuses, effectiveBuilds);
        }
    }

    internal void RecordEffectivePrefix(bool reused)
    {
        ThreadCounters cell = CurrentThreadCounters;
        if (reused) cell.EffectivePrefixReuses++;
        else cell.EffectivePrefixBuilds++;
    }

    internal void RecordListenerPrefix(bool reused)
    {
        ThreadCounters cell = CurrentThreadCounters;
        if (reused) cell.ListenerPrefixReuses++;
        else cell.ListenerPrefixBuilds++;
    }

    internal void RecordListenerSegmentResult(bool split)
    {
        ThreadCounters cell = CurrentThreadCounters;
        if (split) cell.ListenerSplitBuilds++;
        else cell.ListenerWholeBuilds++;
    }

