using System.Reflection;
using System.Runtime.CompilerServices;
using HarmonyLib;
using MegaCrit.Sts2.Core.Hooks;
using MegaCrit.Sts2.Core.Models;

namespace CombatSolver.Engine.Common;

// Root-frozen dispatch metadata for mirrors and the native keyword no-op guard.
// Domain/native listener enumeration remains complete. External and patched hooks
// always retain the original dispatch path.
internal sealed class MirroredHookListenerFilter(bool enabled)
{
    // The projection removes the complete-list capacity pass and repeated getter reads.
    // These exact native getters are field reads in the audited game DLL. Unknown game
    // bodies or getter patches may observe those reads, so retain the complete producer.
    private static readonly Guid AuditedCardGetterModule = new("8a76776c-0ce1-4d4f-90bd-8cce653dad8e");
    private static readonly MethodInfo[] ProjectionReadMethods =
    [
        typeof(CardModel).GetProperty(nameof(CardModel.HasBeenRemovedFromState))!.GetMethod!,
        typeof(CardModel).GetProperty(nameof(CardModel.Affliction))!.GetMethod!,
        typeof(CardModel).GetProperty(nameof(CardModel.Enchantment))!.GetMethod!,
        typeof(PredictedCard).GetProperty(nameof(PredictedCard.Preview))!.GetMethod!,
    ];
    private readonly bool _projectionReadsArePure =
        typeof(CardModel).Module.ModuleVersionId == AuditedCardGetterModule
        && !ProjectionReadMethods.Any(method =>
            Harmony.GetPatchInfo(method) is { } patches && patches.Owners.Count != 0);

    // This filter belongs to one captured root. Only immutable runtime-type layouts
    // cross branches; receiver models remain exclusively in each returned snapshot.
    // A direct-mapped table has bounded retention and needs no worker-side lock.
    internal const int SharedLayoutSlots = 2048;
    private const int MaxSharedLayoutLength = 1024;
    private readonly MirroredHookListenerLayout?[] _sharedLayouts =
        enabled ? new MirroredHookListenerLayout?[SharedLayoutSlots] : [];
    // Keep exact cumulative diagnostics while spreading hot atomic writes. Different
    // thread IDs can select one shard; Interlocked preserves totals even on collisions.
    // Only scalar counters are retained, with no thread, root owner or model references.
    private const int CounterShardCount = 64;
    private const int CounterShardStride = 32;
    private readonly long[] _counterCells = new long[CounterShardCount * CounterShardStride];
    private const int Hits = 0, Misses = 1, Collisions = 2, Bypasses = 3;
    private const int PrefixReuses = 4, PrefixBuilds = 5, SplitBuilds = 6, WholeBuilds = 7;
    private const int EffectiveReuses = 8, EffectiveBuilds = 9;

    [MethodImpl(MethodImplOptions.AggressiveInlining)]
    private void IncrementCounter(int offset)
        => Interlocked.Increment(ref _counterCells[
            (Environment.CurrentManagedThreadId & (CounterShardCount - 1)) * CounterShardStride + offset]);

    internal int StatisticsShardCount => CounterShardCount;

    internal HookListenerSegmentStatistics ListenerSegmentStatistics
    {
        get
        {
            long prefixReuses = 0, prefixBuilds = 0, splitBuilds = 0, wholeBuilds = 0;
            long effectiveReuses = 0, effectiveBuilds = 0;
            for (int shard = 0; shard < CounterShardCount; shard++)
            {
                int start = shard * CounterShardStride;
                prefixReuses += Volatile.Read(ref _counterCells[start + PrefixReuses]);
                prefixBuilds += Volatile.Read(ref _counterCells[start + PrefixBuilds]);
                splitBuilds += Volatile.Read(ref _counterCells[start + SplitBuilds]);
                wholeBuilds += Volatile.Read(ref _counterCells[start + WholeBuilds]);
                effectiveReuses += Volatile.Read(ref _counterCells[start + EffectiveReuses]);
                effectiveBuilds += Volatile.Read(ref _counterCells[start + EffectiveBuilds]);
            }
            return new(prefixReuses, prefixBuilds, splitBuilds, wholeBuilds, effectiveReuses, effectiveBuilds);
        }
    }

    internal void RecordEffectivePrefix(bool reused)
        => IncrementCounter(reused ? EffectiveReuses : EffectiveBuilds);

    internal void RecordListenerPrefix(bool reused)
        => IncrementCounter(reused ? PrefixReuses : PrefixBuilds);

    internal void RecordListenerSegmentResult(bool split)
        => IncrementCounter(split ? SplitBuilds : WholeBuilds);

    internal HookLayoutCacheStatistics Statistics
    {
        get
        {
            long hits = 0, misses = 0, collisions = 0, bypasses = 0;
            for (int shard = 0; shard < CounterShardCount; shard++)
            {
                int start = shard * CounterShardStride;
                hits += Volatile.Read(ref _counterCells[start + Hits]);
                misses += Volatile.Read(ref _counterCells[start + Misses]);
                collisions += Volatile.Read(ref _counterCells[start + Collisions]);
                bypasses += Volatile.Read(ref _counterCells[start + Bypasses]);
            }
            return new(hits, misses, collisions, bypasses);
        }
    }

    private static readonly Dictionary<string, MirroredHookMask> HookNames = new()
    {
        [nameof(AbstractModel.AfterAttack)] = MirroredHookMask.AfterAttack,
        [nameof(AbstractModel.AfterAutoPostPlayPhaseEntered)] = MirroredHookMask.AfterAutoPostPlayPhaseEntered,
        [nameof(AbstractModel.AfterBlockBroken)] = MirroredHookMask.AfterBlockBroken,
        [nameof(AbstractModel.AfterBlockGained)] = MirroredHookMask.AfterBlockGained,
        [nameof(AbstractModel.AfterCardDiscarded)] = MirroredHookMask.AfterCardDiscarded,
        [nameof(AbstractModel.AfterCardDrawn)] = MirroredHookMask.AfterCardDrawn,
        [nameof(AbstractModel.AfterCardDrawnEarly)] = MirroredHookMask.AfterCardDrawnEarly,
        [nameof(AbstractModel.AfterCardExhausted)] = MirroredHookMask.AfterCardExhausted,
