        int applied = ApplyWithBeforeApplied<T>(creature, amount, applier,
            value => Apply<TStat>(creature, sign * value, applier));
        if (alreadyApplied && applied != 0)
            Apply<TStat>(creature, sign * applied, applier);
    }

